#include <stdexcept>

// Function to merge two sorted arrays in-place
// arr1 is the first array with enough space to hold the merged result
// arr2 is the second array
// n1 is the size of arr1 (excluding the space for arr2)
// n2 is the size of arr2
void mergeArrays(int* arr1, int n1, int* arr2, int n2) {
    // Check for invalid input
    if (arr1 == nullptr || arr2 == nullptr) {
        throw std::invalid_argument("Input arrays cannot be null.");
    }
    if (n1 < 0 || n2 < 0) {
        throw std::invalid_argument("Array sizes cannot be negative.");
    }

    // Check if arr1 has enough space to hold the merged array
    if (n1 + n2 > static_cast<int>(sizeof(arr1) / sizeof(arr1[0]))) {
        throw std::length_error("arr1 does not have enough space to hold the merged array.");
    }

    // Initialize pointers
    int i = n1 - 1; // Pointer for arr1
    int j = n2 - 1; // Pointer for arr2
    int k = n1 + n2 - 1; // Pointer for the merged array

    // Merge the arrays
    while (i >= 0 && j >= 0) {
        if (arr1[i] > arr2[j]) {
            arr1[k] = arr1[i];
            i--;
        } else {
            arr1[k] = arr2[j];
            j--;
        }
        k--;
    }

    // If there are remaining elements in arr2, copy them
    while (j >= 0) {
        arr1[k] = arr2[j];
        j--;
        k--;
    }
}

// Example usage
