    // Example arrays
    int arr1[] = {1, 3, 5, 0, 0, 0}; // arr1 has space for 3 more elements
    int arr2[] = {2, 4, 6};
    int n1 = 3; // Size of arr1 excluding the space for arr2
    int n2 = 3; // Size of arr2

    try {
        mergeArrays(arr1, n1, arr2, n2);

        // Print the merged array
        std::cout << "Merged array: ";
        for (int i = 0; i < n1 + n2; ++i) {
            std::cout << arr1[i] << " ";
        }
        std::cout << std::endl;
    } catch (const std::exception& e) {
        std::cerr << "Error: " << e.what() << std::endl;
    }

    return 0;
}

